from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'out/rmuc2027-core-collision-manual'
views=json.loads((OUT/'renders.json').read_text())+json.loads((OUT/'joint-renders.json').read_text())
notes={'tube':'Arm tube: 1,452 → 832 triangles per occurrence. A measured flared profile with 32 radial segments. Open ends and flange retained; fine grooves omitted. Maximum sampled difference 0.556 mm. Saves 1,240 triangles across two placements.', 'sleeve':'Head sleeve: 1,008 → 48 triangles per occurrence. An open cylinder with 24 segments replaces thread corrugation. Maximum sampled difference 0.923 mm. Saves 1,920 triangles across two placements. Crucial slotted face is unchanged.', 'arm':'Only the long flanged tube changes in this candidate. The two local profile edits together save 3,160 placed collision triangles; all visual assets remain unchanged.', 'head':'Only one small threaded sleeve changes in this head candidate. The slotted face, target and other head geometry remain exact to installed collision. This is a first local trial, not a whole-head simplification.', 'joint':'Separate aggressive prototype: one solid 24-segment cylinder replaces a 3,187-triangle hollow housing with 96 triangles, saving 6,182 placed triangles. All bores are intentionally filled. Its enclosing outline is larger; clearance/contact review is required. This prototype is not combined with the two local profile edits.', 'joint-context':'Solid-cylinder prototype in the complete arm scope. Filling internal voids is intentional, but the enlarged exterior needs a clearance check. All other arm parts remain installed geometry.'}
s={'views':[{k:v[k]for k in ['key','label','view','stage','path']}for v in views],'notes':notes}
html='''<!doctype html><html><head><style>body{font:14px var(--font-sans);color:var(--foreground)}nav{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}select{font:inherit;padding:8px;background:var(--secondary);color:inherit;border:1px solid var(--border);border-radius:6px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}img{width:100%;display:block}p{line-height:1.5}small{color:var(--muted-foreground)}@media(max-width:480px){.grid{grid-template-columns:1fr}}</style></head><body><p><b>Tech Core · collision shape trials</b><br>Installed geometry is the reference. Visual assets remain unchanged.</p><nav><select id="part"></select><select id="view"><option value="oblique">Oblique</option><option value="reverse">Reverse</option></select></nav><div class="grid"><div><b>Installed collision</b><img id="before"></div><div><b>Candidate collision</b><img id="after"></div></div><p id="note"></p><small>Matched cameras within each comparison. Isolated collision scopes, imported proxy colors and flat shading. Inspection artifacts only; nothing installed. Surface samples do not prove continuous geometry or contact equivalence.</small><script>const data=DATA;const part=document.querySelector('#part');const seen=new Set();for(const v of data.views){if(seen.has(v.key))continue;seen.add(v.key);const o=document.createElement('option');o.value=v.key;o.textContent=v.label;part.append(o)}function update(){for(const[stage,id]of [['installed','before'],['candidate','after']]){document.getElementById(id).src=data.views.find(v=>v.key===part.value&&v.stage===stage&&v.view===document.querySelector('#view').value).path}document.querySelector('#note').textContent=data.notes[part.value]}document.querySelectorAll('select').forEach(e=>e.onchange=update);update();</script></body></html>'''.replace('DATA',json.dumps(s))
(OUT/'gallery.html').write_text(html)
